import { setup, assign } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'countErrorLines',
  context: {
    files: [
      'api-gateway.log', 'auth.log', 'billing.log', 'cart.log', 'catalog.log',
      'checkout.log', 'email.log', 'fraud.log', 'geo.log', 'image.log',
      'inventory.log', 'ledger.log', 'loyalty.log', 'media.log', 'notify.log',
      'orders.log', 'payments.log', 'pricing.log', 'profile.log', 'queue.log',
      'ranking.log', 'recs.log', 'reviews.log', 'search.log', 'session.log',
      'shipping.log', 'tax.log', 'wishlist.log'
    ],
    currentIndex: 0,
    results: []
  },
  initial: 'readNextFile',
  states: {
    readNextFile: {
      always: [
        {
          guard: ({ context }) => context.currentIndex < context.files.length,
          target: 'readingFile'
        },
        {
          target: 'done'
        }
      ]
    },
    readingFile: {
      entry: toolCall('fs.read_file', ({ context }) => ({
        path: `logs/services/${context.files[context.currentIndex]}`
      }), { id: 'readFile' }),
      on: {
        TOOL_RESULT: {
          target: 'countErrors',
          actions: assign({
            currentIndex: ({ context }) => context.currentIndex + 1
          }),
          guard: ({ event }) => event.callId === 'readFile'
        },
        TOOL_ERROR: {
          target: 'readNextFile',
          actions: assign({
            results: ({ context, event }) => [
              ...context.results,
              `${context.files[context.currentIndex]}: ERROR (read failed)`
            ],
            currentIndex: ({ context }) => context.currentIndex + 1
          }),
          guard: ({ event }) => event.callId === 'readFile'
        }
      }
    },
    countErrors: {
      entry: assign({
        results: ({ context, event }) => {
          const fileContent = event.result;
          const fileName = context.files[context.currentIndex - 1];
          const lines = fileContent.split('\n');
          const errorCount = lines.filter(line => line.includes('ERROR')).length;
          return [
            ...context.results,
            `${fileName}: ${errorCount}`
          ];
        }
      }),
      target: 'readNextFile'
    },
    done: {
      type: 'final'
    }
  },
  output: ({ context }) => context.results
});

